  "pricing.docTitle": "Prijzen van de Trip Pass",
  "pricing.compareTitle": "Wat gratis blijft en wat een pass toevoegt",
  "pricing.passCol": "Een Trip Pass voegt toe",
  "pricing.free1": "Elke plek, met prijs en kaart",
