  "pricing.afterQ": "Wat gebeurt er na {days} dagen?",
  "pricing.afterA": "De Trip Pass stopt. Er wordt niets verlengd en niets meer afgeschreven. Je reizen blijven bewaard en plannen blijft gratis. Exports en de extra plannen wachten op een nieuwe pass.",
  "pricing.restoreQ": "Ik heb op een ander apparaat betaald. Waar is mijn pass?",
  "pricing.restoreA": "Je pass hoort bij je account, niet bij het apparaat. Log in met het account waarmee je betaalde en hij staat er. Nog steeds niet? Schrijf naar {email}.",
  "pricing.restoreGo": "Controleer mijn pass opnieuw",
  "pricing.restoreSignIn": "Inloggen",
