  "pass.continueAddDays": "{n} dagen toevoegen, {price}",
  "pass.carryOver": "Je resterende Trip Pass-dagen blijven behouden.",
  "pass.current1": "Je hebt een {name} met nog 1 dag.",
  "pass.cancellingNote": "Je jaarabonnement stopt op {date}. Houd het aan en het verlengt zoals eerst.",
  "pass.resume": "Jaarabonnement houden",
  "account.fqgPlanning": "Plannen",
  "account.fqgPrices": "Prijzen",
  "account.fqgPasses": "Passes en betalen",
  "account.fqgAccount": "Account en gegevens",
  "account.fq.planQ": "Hoe plan ik een reis?",
  "account.fq.planA": "Open de Reisplanner, kies je data en plekken, en Carta zet de stops op volgorde en prijst elk bed, elke dag en elk traject. De Dagplanner vult daarna elke dag per uur.",
  "account.fq.togetherQ": "Kan ik samen met vrienden een reis plannen?",
  "account.fq.togetherA": "Ja. Kies in Mijn reizen Uitnodigen bij een reis: wie de link heeft, kan inloggen en de route mee aanpassen. Een link om te bekijken werkt zonder account.",
  "account.fq.bookQ": "Kan ik via Carta boeken?",
  "account.fq.bookA": "Nee. Carta prijst en plant de reis en stuurt je dan naar de luchtvaartmaatschappij, het spoor of de verhuurder om daar rechtstreeks te boeken.",
  "account.fq.missingQ": "Mijn plaats ontbreekt. Wat nu?",
  "account.fq.missingA": "De Dagplanner werkt toch: typ de plaats en hij zoekt die live op. De catalogus groeit met elke update.",
  "account.fq.differentQ": "Wat is het verschil tussen Carta en Google Maps of Wanderlog?",
  "account.fq.differentA": "Google Maps brengt je erheen en Wanderlog bewaart het plan dat je zelf intypte, maar geen van beide weet wat een bed of een dag kost. Carta plant de hele reis op één plek, met wat elke dag kost: een bed plus eten en drinken, geprijsd voor elke plek. Carta navigeert nooit, dus elke dag en rit opent in Google Maps.",
  "account.fq.dayQ": "Wat zit er in de prijs per dag?",
  "account.fq.dayA": "Eén persoon, één dag: een bed voor de nacht plus eten en drinken (een maaltijd aan tafel, een snelle maaltijd, drankjes), volgens je Lifestyle. Niet inbegrepen: de reis ernaartoe, lokaal vervoer en tickets.",
  "account.fq.estQ": "Waarom staat er gesch. bij een prijs?",
  "account.fq.estA": "Het is een schatting: de prijzen van die plaats zijn niet gemeten, dus Carta gebruikt het niveau van het land. Een gemeten prijs heeft geen markering.",
  "account.fq.lifestyleQ": "Waarom veranderden de prijzen toen ik mijn Lifestyle aanpaste?",
  "account.fq.lifestyleA": "Omdat het jouw prijzen zijn. Een slaapzaalbed en een hele woning met uit eten zijn andere reizen, en één instelling stuurt elk bedrag in de app.",
  "account.fq.flightsQ": "Toont Carta vliegprijzen?",
  "account.fq.flightsA": "Ja. Carta toont de goedkoopste vlucht van Google Flights voor jouw dagen, met de maatschappij, de tijden en wanneer hij gecontroleerd is, plus de gebruikelijke bagagekosten als schatting. Een ticket dat je zelf invult, vervangt hem.",
  "account.fq.addsQ": "Wat voegt een pass toe?",
  "account.fq.addsA": "Gratis houdt {freePlans} plannen van de Carta-bot en één bewaarde reis. Een Trip Pass voegt exports naar PDF, agenda en kaart toe, al je reizen bewaard, boekingen inlezen, meer dagplannen van de Carta-bot en live zoeken naar evenementen en openingstijden. Een reis delen en samen plannen met vrienden blijven gratis.",
  "account.fq.differenceQ": "Wat is het verschil tussen de Trip Pass en het jaarabonnement?",
  "account.fq.differenceA": "De Trip Pass kost eenmalig {tripPrice} en loopt {tripDays} dagen, zonder verlenging. Het jaarabonnement kost {yearPrice} per jaar en verlengt tot je opzegt.",
  "account.fq.cancelQ": "Hoe zeg ik het jaarabonnement op?",
  "account.fq.cancelA": "Kies in Account, onder Je abonnement, voor Jaarabonnement opzeggen. Het loopt tot het einde van het betaalde jaar en er wordt niets meer afgeschreven.",
  "account.fq.refundQ": "Kan ik mijn geld terugkrijgen?",
  "account.fq.refundA": "Ja, binnen 14 dagen na betaling als je de pass of het abonnement niet gebruikte. Schrijf naar {email} vanaf het adres van je account.",
  "account.fq.needQ": "Heb ik een account nodig?",
  "account.fq.needA": "Niet om te bekijken of te plannen. Een account bewaart je reizen op elk apparaat, opent de Carta-bot en laat je samen met vrienden plannen.",
  "account.fq.whereQ": "Waar worden mijn reizen bewaard?",
  "account.fq.whereA": "Op je account als je ingelogd bent, dus ze openen op elk apparaat. Uitgelogd blijven ze in deze browser.",
  "account.fq.deleteQ": "Hoe verwijder ik mijn account en gegevens?",
  "account.fq.deleteA": "Open in Account Jouw gegevens en kies Verwijder mijn account. Alles verdwijnt meteen van de servers van Carta; je kunt eerst een kopie downloaden.",
  "account.faqSearch": "Zoek in de vragen",
